const supervise=(c,options)=>{let clock=1800000000000;const pause=options.pause&&!options.now?async(ms,signal)=>{clock+=ms;return options.pause(ms,signal);}:options.pause;return actualSupervise(c,{health:()=>({ok:true}),now:()=>clock,...options,...(pause?{pause}:{})});};
async function fixture(names=['isso','promise']){const home=await mkdtemp(join(tmpdir(),'flora-service-')),runtime=join(home,'.flora','pc-runner-uulab');await mkdir(runtime,{recursive:true,mode:0o700});await mkdir(join(runtime,'scratch'),{mode:0o700});const configs=names.map(name=>join(runtime,name+'.json'));for(const p of configs)await writeFile(p,'{"token":"never-log-secret"}',{mode:0o600});const c={runtimeDirectory:runtime,nodePath:process.execPath,runnerMain:'/trusted/main.js',runnerConfigs:configs,path:'/trusted/bin:/usr/bin:/bin',limaHome:join(runtime,'lima'),dockerHost:'unix://'+join(runtime,'lima','socket.sock'),pollIntervalMs:10000};const path=join(runtime,'service.json');await writeFile(path,JSON.stringify(c),{mode:0o600});return {home,runtime,c,path,cleanup:()=>rm(home,{recursive:true,force:true})};}
test('logs contain only fixed fields, never token, raw stderr, recovery path or arbitrary diagnostic stage',()=>{assert.equal(sanitizedLine('secret token'),null);const r=sanitizedLine(JSON.stringify({state:'publication_unknown',recoveryJournal:'/secret/token',token:'never-log-secret',jobId:'never-log-secret'}));assert.deepEqual(r,{state:'publication_unknown'});assert.deepEqual(sanitizedLine('{"diagnostic":true,"stage":"secret-token","code":"unknown-secret","httpStatus":403}'),{diagnostic:true,httpStatus:403});});
test('compiler diagnostics preserve fixed child cause separately from control codes and exclude unknown values',()=>{
 assert.deepEqual(sanitizedLine('{"diagnostic":true,"stage":"compiler-expo-export","code":"PROCESS_TIMEOUT","token":"never-log-secret"}'),{diagnostic:true,stage:'compiler-expo-export',compilerCode:'PROCESS_TIMEOUT'});
 assert.deepEqual(sanitizedLine('{"diagnostic":true,"stage":"dependency-preparation-npm-install","code":"NPM_ENOTCACHED"}'),{diagnostic:true,stage:'dependency-preparation-npm-install',compilerCode:'NPM_ENOTCACHED'});
 assert.deepEqual(sanitizedLine('{"diagnostic":true,"stage":"claim","code":"PROCESS_TIMEOUT"}'),{diagnostic:true,stage:'claim'});
 assert.deepEqual(sanitizedLine('{"diagnostic":true,"stage":"compiler-expo-export","code":"CONFIG_CHANGED"}'),{diagnostic:true,stage:'compiler-expo-export',code:'CONFIG_CHANGED'});
 for(const line of ['{"diagnostic":true,"stage":"compiler-/private/token","code":"PROCESS_TIMEOUT"}','{"diagnostic":true,"stage":"compiler-expo-export","code":"TOKEN_never-log-secret"}','{"diagnostic":true,"stage":"claim","compilerCode":"PROCESS_TIMEOUT","path":"never-log-secret"}']){const value=sanitizedLine(line);assert.ok(!JSON.stringify(value).includes('never-log-secret'));assert.equal(value.compilerCode,undefined);assert.equal(value.code,undefined);}
});
test('visible compiler timeout remains a normal export failure and does not stop later app claims',async()=>{
 const f=await fixture(),controller=new AbortController(),calls=[],logs=[];
 const source="console.log(JSON.stringify({diagnostic:true,stage:'compiler-expo-export',code:'PROCESS_TIMEOUT'}));console.error('never-log-secret');console.log(JSON.stringify({diagnostic:true,stage:'compiler',code:'EXPORT_FAILED'}));console.log(JSON.stringify({state:'failed',code:'EXPORT_FAILED'}));process.exitCode=1";
 try{assert.equal(await supervise(f.c,{presence:false,signal:controller.signal,run:async(_command,args,env,signal)=>{calls.push(args[2]);return calls.length===1?runChild(process.execPath,['-e',source],env,signal):{exitCode:0,records:[{state:'empty'}],overflow:false};},pause:async()=>{if(calls.length===3)controller.abort();},log:async event=>logs.push(event),fatal:async()=>assert.fail('compiler detail must not become a fatal control code')}),0);
  assert.deepEqual(calls,[...f.c.runnerConfigs,f.c.runnerConfigs[0]]);assert.deepEqual(logs.find(event=>event.compilerCode),{appIndex:0,diagnostic:true,stage:'compiler-expo-export',compilerCode:'PROCESS_TIMEOUT'});assert.ok(!JSON.stringify(logs).includes('never-log-secret'));await assert.rejects(lstat(join(f.runtime,'fatal-stop')),{code:'ENOENT'});
 }finally{controller.abort();await f.cleanup();}
});
test('compiler detail cannot make claim or presence failures retryable or hide authority faults',async()=>{
 const f=await fixture(['isso']);try{for(const records of [[{diagnostic:true,stage:'claim',compilerCode:'PROCESS_TIMEOUT'}],[{diagnostic:true,stage:'claim',code:'RUNNER_TRANSPORT_UNAVAILABLE',compilerCode:'PROCESS_TIMEOUT'}],[sanitizedLine('{"diagnostic":true,"stage":"claim","code":"PROCESS_TIMEOUT"}')],[sanitizedLine('{"diagnostic":true,"stage":"compiler-expo-export","code":"CONFIG_CHANGED"}'),{state:'failed',code:'EXPORT_FAILED'}]]){
   assert.equal(await supervise(f.c,{presence:false,signal:new AbortController().signal,run:async()=>({exitCode:1,records,overflow:false}),pause:async()=>assert.fail('compiler details cannot permit claim retries'),log:async()=>{},fatal:async()=>{}}),1);
  }
  const controller=new AbortController(),stops=[];await presenceLoop(f.c,{signal:controller.signal,env:{},run:async()=>({exitCode:1,records:[{diagnostic:true,stage:'runner-execution',code:'RUNNER_TRANSPORT_UNAVAILABLE',compilerCode:'PROCESS_TIMEOUT'}],overflow:false}),pause:async()=>assert.fail('new detail fields are not admitted in presence recovery'),log:async()=>{},stop:async(...args)=>{stops.push(args);controller.abort();}});assert.deepEqual(stops,[['presence-fatal-stop',0]]);
 }finally{await f.cleanup();}
});
