test('private validated configuration rejects permissions, symlinks, credentials and duplicate apps',async()=>{const f=await fixture();try{assert.deepEqual(await readConfig(f.path),f.c);await chmod(f.c.runnerConfigs[0],0o644);await assert.rejects(readConfig(f.path),/PRIVATE/);await chmod(f.c.runnerConfigs[0],0o600);for(const change of [{token:'secret'},{runnerConfigs:[f.c.runnerConfigs[0],f.c.runnerConfigs[0]]},{pollIntervalMs:9999},{vmStart:['/bin/sh','-c','evil','-y']}]){await writeFile(f.path,JSON.stringify({...f.c,...change}));await assert.rejects(readConfig(f.path),/INVALID/);}await writeFile(f.path,JSON.stringify(f.c));await rm(f.c.runnerConfigs[0]);await symlink(f.c.runnerConfigs[1],f.c.runnerConfigs[0]);await assert.rejects(readConfig(f.path),/PRIVATE/);}finally{await f.cleanup();}});
test('alternates two app configs sequentially, bounded polling, allows normal export failure',async()=>{const f=await fixture(),controller=new AbortController(),calls=[],logs=[];let active=0;try{const exit=await supervise(f.c,{presence:false,signal:controller.signal,run:async(command,args,env)=>{assert.equal(++active,1);assert.equal(env.DOCKER_HOST,f.c.dockerHost);assert.equal(env.TMPDIR,join(f.runtime,'scratch'));assert.equal(env.GITHUB_TOKEN,undefined);calls.push(args);active--;return {exitCode:calls.length===2?1:0,records:[{state:calls.length===2?'failed':'empty',...(calls.length===2?{code:'EXPORT_FAILED'}:{})}]};},pause:async(ms)=>{assert.equal(ms,10000);if(calls.length===3)controller.abort();},log:async r=>logs.push(r),fatal:async()=>assert.fail('unexpected fatal')});assert.equal(exit,0);assert.deepEqual(calls.map(a=>a[2]),[f.c.runnerConfigs[0],f.c.runnerConfigs[1],f.c.runnerConfigs[0]]);assert.equal(logs.length,3);}finally{await f.cleanup();}});
test('authority, transport, publication and recovery failures stop once, retain journal and fatal latch',async()=>{for(const result of [{exitCode:1,records:[{code:'UNAUTHENTICATED'}]},{exitCode:1,records:[{state:'publication_unknown'}]},{exitCode:1,records:[{state:'failed',code:'CONFIG_CONFLICT'}]},{exitCode:1,records:[{diagnostic:true,httpStatus:409,code:'BUSY'},{state:'failed',code:'EXPORT_FAILED'}]},{exitCode:1,records:[],overflow:true}]){const f=await fixture();try{const journal=join(f.runtime,'recovery.json');await writeFile(journal,'preserved',{mode:0o600});let calls=0;assert.equal(await supervise(f.c,{presence:false,signal:new AbortController().signal,run:async()=>{calls++;return result;},log:async()=>{},pause:async()=>assert.fail('fatal must not poll')}),1);assert.equal(calls,1);assert.equal(await readFile(journal,'utf8'),'preserved');assert.equal((await lstat(join(f.runtime,'fatal-stop'))).mode&0o777,0o600);}finally{await f.cleanup();}}});
