const dockerUnavailable=()=>({exitCode:1,records:[{diagnostic:true,stage:'runner-initialization',code:'DOCKER_DAEMON_UNAVAILABLE'},{code:'DOCKER_DAEMON_UNAVAILABLE'}]});
test('preclaim Docker outage after healthy preflight rotates apps, backs off and preserves credentials and journals',async()=>{
 const f=await fixture(['isso','promise','reward']),controller=new AbortController(),calls=[],waits=[],logs=[];
 try{const before=await Promise.all(f.c.runnerConfigs.map(path=>readFile(path,'utf8'))),journal=join(f.runtime,'recovery.json');await writeFile(journal,'immutable-receipt',{mode:0o600});
  assert.equal(await supervise(f.c,{presence:false,signal:controller.signal,run:async(command,args)=>{calls.push(args[2]);return calls.length===1||calls.length===4?dockerUnavailable():{exitCode:0,records:[{state:'empty'}]};},pause:async ms=>{waits.push(ms);if(calls.length===7)controller.abort();},log:async r=>logs.push(r),fatal:async()=>assert.fail('availability before claim must recover')}),0);
  assert.deepEqual(calls,[...f.c.runnerConfigs,...f.c.runnerConfigs,f.c.runnerConfigs[0]]);assert.deepEqual(waits,[10000,10000,10000,20000,10000,10000,10000]);assert.equal(logs.filter(r=>r.event==='isolation-retry').length,2);
  assert.equal(await readFile(journal,'utf8'),'immutable-receipt');assert.deepEqual(await Promise.all(f.c.runnerConfigs.map(path=>readFile(path,'utf8'))),before);await assert.rejects(lstat(join(f.runtime,'fatal-stop')),{code:'ENOENT'});
 }finally{await f.cleanup();}
});
