   assert.equal(await supervise(f.c,{presence:false,signal:controller.signal,run:async(command,args)=>{assert.equal(++active,1);calls.push(args);await Promise.resolve();active--;return calls.length===1?failure:{exitCode:0,records:[{state:'empty'}]};},pause:async ms=>{waits.push(ms);if(calls.length===3)controller.abort();},log:async r=>logs.push(r),fatal:async()=>assert.fail('recoverable claim must not latch')}),0);
