test('LaunchAgent restarts unsuccessful exits without credentials and explicit lifecycle does not expose launchctl output',async()=>{const f=await fixture();try{const bin=join(f.runtime,'bin');await mkdir(bin,{mode:0o700});const supervisor=join(bin,'supervisor.mjs');await writeFile(supervisor,'private trusted code',{mode:0o600});const xml=plist(f.c,f.path,supervisor);assert.ok(xml.includes('<key>KeepAlive</key><dict><key>SuccessfulExit</key><false/></dict>'));assert.ok(xml.includes('<key>RunAtLoad</key><true/>'));assert.ok(!xml.includes('never-log-secret'));assert.deepEqual(await lifecycle('install',{home:f.home,configPath:f.path,supervisorPath:supervisor}),{state:'installed'});await writeFile(join(f.runtime,'fatal-stop'),'old',{mode:0o600});const calls=[];let loaded=false;const exec=a=>{calls.push(a);if(a[0]==='print')return {status:loaded?0:1,stdout:'service = {\n state = not running\n}\n'};if(a[0]==='bootstrap')loaded=true;if(a[0]==='bootout')loaded=false;return {status:0,stdout:'secret'};};assert.deepEqual(await lifecycle('start',{home:f.home,exec}),{state:'started'});assert.ok(calls.some(a=>a[0]==='bootstrap'));await assert.rejects(lstat(join(f.runtime,'fatal-stop')),e=>e.code==='ENOENT');assert.deepEqual(await lifecycle('status',{home:f.home,exec}),{state:'loaded-idle',loaded:true});assert.deepEqual(await lifecycle('stop',{home:f.home,exec}),{state:'stopped'});}finally{await f.cleanup();}});

