test('generated launchd configuration restarts unsuccessful exits and retains startup and shutdown bounds',async t=>{
 if(process.platform!=='darwin'){t.skip('macOS plutil boundary');return;}
 const f=await fixture();try{const file=join(f.runtime,'launchd.plist');await writeFile(file,plist(f.c,f.path,'/trusted/supervisor.mjs'),{mode:0o600});const result=spawnSync('/usr/bin/plutil',['-convert','json','-o','-',file],{encoding:'utf8',timeout:3000});assert.equal(result.status,0);const parsed=JSON.parse(result.stdout);assert.deepEqual(parsed.KeepAlive,{SuccessfulExit:false});assert.equal(parsed.RunAtLoad,true);assert.equal(parsed.ThrottleInterval,30);assert.equal(parsed.ExitTimeOut,40);assert.ok(!result.stdout.includes('never-log-secret'));
 }finally{await f.cleanup();}
});
test('actual CLI preclaim Docker failure survives sanitized child output and resumes only healthy empty claims',async()=>{
 const f=await fixture(),controller=new AbortController(),logs=[],requests=[],waits=[],bin=join(f.runtime,'tools'),counter=join(f.runtime,'docker-calls.json');let server;
 try{await mkdir(bin,{mode:0o700});await writeFile(join(bin,'docker'),`#!${process.execPath}\nconst fs=require('node:fs'),path=${JSON.stringify(counter)};let count=0;try{count=JSON.parse(fs.readFileSync(path,'utf8'))}catch{}fs.writeFileSync(path,JSON.stringify(++count));if(process.argv[2]!=='version')process.exitCode=2;else if(count===1){console.error('never-log-secret');process.exitCode=1}else console.log('29.0.0');\n`,{mode:0o755});
  server=createServer((req,res)=>{assert.equal(req.url,'/api/runner/claim');requests.push(req.headers.authorization);res.writeHead(204);res.end();});await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  const tokens=['runner_isso.'+'a'.repeat(43),'runner_promise.'+'b'.repeat(43)],origin='http://127.0.0.1:'+server.address().port;
  for(let i=0;i<f.c.runnerConfigs.length;i++)await writeFile(f.c.runnerConfigs[i],JSON.stringify({origin,token:tokens[i],dockerImage:'node@sha256:'+'a'.repeat(64),recoveryDirectory:join(f.runtime,'recovery-'+i)}),{mode:0o600});
  const before=await Promise.all(f.c.runnerConfigs.map(path=>readFile(path,'utf8'))),journal=join(f.runtime,'unrelated-recovery.json');await writeFile(journal,'preserved',{mode:0o600});
  const c={...f.c,path:bin+':/usr/bin:/bin',runnerMain:fileURLToPath(new URL('../../packages/ota-runner/dist/main.js',import.meta.url))};
  assert.equal(await supervise(c,{presence:false,signal:controller.signal,pause:async ms=>{waits.push(ms);if(JSON.parse(await readFile(counter,'utf8'))===3)controller.abort();},log:async r=>logs.push(r),fatal:async()=>assert.fail('proven preclaim outage must retry')}),0);
  assert.deepEqual(requests,['Bearer '+tokens[1],'Bearer '+tokens[0]]);assert.deepEqual(waits,[10000,10000,10000]);assert.equal(logs.filter(r=>r.event==='isolation-retry').length,1);assert.equal(logs.filter(r=>r.state==='empty').length,2);assert.ok(!JSON.stringify(logs).includes('never-log-secret'));assert.ok(tokens.every(token=>!JSON.stringify(logs).includes(token)));
  assert.equal(await readFile(journal,'utf8'),'preserved');assert.deepEqual(await Promise.all(f.c.runnerConfigs.map(path=>readFile(path,'utf8'))),before);await assert.rejects(lstat(join(f.runtime,'fatal-stop')),{code:'ENOENT'});
 }finally{if(server)await new Promise(resolve=>{server.close(resolve);server.closeAllConnections();});await f.cleanup();}
});


test('three idle apps reduce old 120 claims per hour with bounded fair per-app cooldown',async()=>{
 const f=await fixture(['isso','promise','reward']),controller=new AbortController(),calls=[],c={...f.c,pollIntervalMs:30000};let time=1800000000000;const start=time;
 try{assert.equal(await supervise(c,{presence:false,now:()=>time,signal:controller.signal,run:async(_command,args)=>{calls.push({app:args[2],time:time-start});return {exitCode:0,records:[{state:'empty'}]};},pause:async ms=>{time+=ms;if(time-start>=3600000)controller.abort();},log:async()=>{},fatal:async()=>assert.fail('idle must not latch')}),0);
  assert.ok(calls.length<=48,`old30sloop120/hour; actual ${calls.length}`);assert.deepEqual(calls.slice(0,3).map(row=>row.app),c.runnerConfigs);
  for(const app of c.runnerConfigs){const times=calls.filter(row=>row.app===app).map(row=>row.time);assert.ok(times.length>=10);for(let i=1;i<times.length;i++)assert.ok(times[i]-times[i-1]<=300000,`${app} fair maximum idle gap`);}
 }finally{await f.cleanup();}
});
test('idle app receives a queued job within five minutes then resumes base polling without starving siblings',async()=>{
 const f=await fixture(['isso','promise','reward']),controller=new AbortController();let time=1800000000000,received=null;const start=time,calls=[];
 try{assert.equal(await supervise({...f.c,pollIntervalMs:30000},{presence:false,now:()=>time,signal:controller.signal,run:async(_command,args)=>{const app=args[2];calls.push({app,time:time-start});if(app===f.c.runnerConfigs[0]&&time-start>=1000000&&received===null){received=time-start;return {exitCode:0,records:[{state:'succeeded'}]};}return {exitCode:0,records:[{state:'empty'}]};},pause:async ms=>{time+=ms;if(received!==null&&calls.filter(row=>row.app===f.c.runnerConfigs[0]&&row.time>received).length>=2)controller.abort();},log:async()=>{},fatal:async()=>assert.fail('normal work must not latch')}),0);
  assert.ok(received-1000000<=300000);const follow=calls.filter(row=>row.app===f.c.runnerConfigs[0]&&row.time>received);assert.ok(follow[0].time-received<=30000*f.c.runnerConfigs.length,'nonempty resets eligibility to base interval; fair sibling turns remain');assert.ok(calls.some(row=>row.app===f.c.runnerConfigs[1]&&row.time>received));
 }finally{await f.cleanup();}
});
